import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Select } from 'antd';
import cn from 'classnames';

import { useMetaRetrieveQuery } from 'shared/api';
import { CAPS_OPTIONS } from 'shared/consts';

import { OPTIONS_MAX_HEIGHT_MAIN } from '../../consts';
import { useFilters } from '../../hooks/useFilters';
import { EFilters } from '../../model/enums';
import { ExtendedFilters } from '../ExtendedFilters/ExtendedFilters';

import styles from './MainFilters.module.scss';

interface IMainFiltersProps extends HTMLAttributes<HTMLDivElement> {}

export const MainFilters: FC<IMainFiltersProps> = ({ className, ...props }) => {
	const { t } = useTranslation();
	const { data: metaData, isLoading: isMetaLoading } = useMetaRetrieveQuery();
	const { getALLFilterValues, getFiltersCount, onFilterChange } = useFilters();

	return (
		<div {...props} className={cn(className, styles.mainFilters)}>
			<Select
				className={styles.select}
				value={getALLFilterValues(EFilters.CATEGORY)}
				options={metaData?.categoryOptions}
				loading={isMetaLoading}
				onChange={(value) => onFilterChange(EFilters.CATEGORY, value)}
				placeholder={t('Category')}
				size="large"
				mode="multiple"
				showSearch
				listHeight={OPTIONS_MAX_HEIGHT_MAIN}
				allowClear
				maxTagCount={'responsive'}
			/>

			<Select
				className={styles.select}
				onChange={(value) => onFilterChange(EFilters.GEO, value)}
				value={getALLFilterValues(EFilters.GEO)}
				options={metaData?.countryOptions}
				loading={isMetaLoading}
				placeholder={t('Geo')}
				size="large"
				mode="multiple"
				showSearch
				listHeight={OPTIONS_MAX_HEIGHT_MAIN}
				allowClear
				maxTagCount={'responsive'}
			/>

			<Select
				className={styles.select}
				onChange={(value) => onFilterChange(EFilters.CAP, value)}
				value={getALLFilterValues(EFilters.CAP)}
				options={CAPS_OPTIONS}
				placeholder={t('Cap')}
				size="large"
				allowClear
			/>

			<ExtendedFilters appliedFiltersCount={getFiltersCount()} />
		</div>
	);
};
