import { FC, HTMLAttributes, ReactNode } from 'react';

import { Typography } from 'antd';
import cn from 'classnames';

import styles from './ListTopbar.module.scss';

interface IListTopbarProps extends HTMLAttributes<HTMLDivElement> {
	leftComponent: ReactNode;
	rightText?: string;
	rightData?: string | number;
}

export const ListTopbar: FC<IListTopbarProps> = ({ className, leftComponent, rightData, rightText, ...props }) => {
	return (
		<div {...props} className={cn(className, styles.listTopbar)}>
			{leftComponent}
			{rightText && (
				<Typography.Text type={'secondary'}>
					{rightText}: {rightData}
				</Typography.Text>
			)}
		</div>
	);
};
