import { FC, HTMLAttributes, useState } from 'react';
import { useTranslation } from 'react-i18next';

import { Popover } from 'antd';
import cn from 'classnames';

import CheckIcon from 'assets/images/icons/check.svg?react';
import SortIcon from 'assets/images/icons/sort.svg?react';
import { EPaginationParams } from 'features/Pagination';
import { useCommonSlice, useSearchParamsWithHash } from 'shared/hooks';

import { ISortItem } from '../../types/types';
import { getValue, isActive, isDesc } from '../../utils/sort';

import styles from './Sort.module.scss';

interface ISortProps extends HTMLAttributes<HTMLDivElement> {
	sortItems: ISortItem[];
	defaultSort?: ISortItem;
}

export const Sort: FC<ISortProps> = ({
	className,
	sortItems,
	defaultSort = { name: 'name', text: 'Alphabetically (Ascending)' },
	...props
}) => {
	const { t } = useTranslation();
	const [searchParams, setSearchParams] = useSearchParamsWithHash();
	const { clearInfinityScroll } = useCommonSlice();
	const selectedSort = sortItems.find(({ name }) => name === getValue()) || defaultSort;
	const [isOpened, setIsOpened] = useState(false);

	const onSort = (sort: ISortItem) => {
		searchParams.set('ordering', sort.name);

		searchParams.delete(EPaginationParams.OFFSET);
		clearInfinityScroll();

		setSearchParams(searchParams);
		setIsOpened(false);
	};

	return (
		<div {...props}>
			<Popover
				open={isOpened}
				onOpenChange={setIsOpened}
				content={
					<div className={styles.items}>
						{sortItems.map((sort) => (
							<button
								key={`sort_item_${sort.name}`}
								className={cn(styles.item, { [styles.active]: isActive(sort, defaultSort) })}
								onClick={() => onSort(sort)}>
								<span className={styles.check}>{isActive(sort, defaultSort) && <CheckIcon />}</span>
								{sort.text}
							</button>
						))}
					</div>
				}
				arrow={false}
				trigger={'click'}>
				<button className={cn(className, styles.sort)}>
					<span>{t('Sort by')}:</span>
					<span className={styles.sort__current}>{selectedSort.text.replace(/\(([^)]+)\)/g, '')}</span>
					<SortIcon className={cn(styles.sort__icon, { [styles.desc]: isDesc() })} />
				</button>
			</Popover>
		</div>
	);
};
