import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';
import { useDispatch } from 'react-redux';
import { useNavigate } from 'react-router-dom';

import { Button, Typography } from 'antd';
import cn from 'classnames';

import { AppDispatch } from 'app/appStore';
import noImageIcon from 'assets/images/no-image.svg';
import { openJoinModal } from 'features/JoinOffer';
import { CATEGORIES } from 'shared/consts';
import { useMedia } from 'shared/hooks';
import { EGaCategories, EGaEvents, EGaTypes, EMainRoutes } from 'shared/typings';
import { InfoTooltip } from 'shared/ui';
import { sendGaEvent } from 'shared/utils';

import { OfferRead } from '../../api/codegen.api';
import { OfferCardColumn } from '../OfferCardColumn/OfferCardColumn';

import styles from './OfferCard.module.scss';

interface IOfferCardProps extends HTMLAttributes<HTMLElement> {
	offer: OfferRead;
}

export const OfferCard: FC<IOfferCardProps> = ({ className, offer, ...props }) => {
	const { t } = useTranslation();
	const navigate = useNavigate();
	const isDesktop = useMedia('desktop');
	const dispatch = useDispatch<AppDispatch>();

	const handleJoinClick = (event: React.MouseEvent<HTMLButtonElement, MouseEvent>) => {
		event.stopPropagation();
		dispatch(openJoinModal(offer));
		sendGaEvent(EGaEvents.CLICK_JOIN, {
			event_option1: EGaCategories.CATALOG,
			event_option2: EGaTypes.BRANDS_CATALOG,
		});
	};

	return (
		<div
			{...props}
			className={cn(className, styles.card)}
			onClick={() => navigate(`/${EMainRoutes.CATALOG}/${EMainRoutes.OFFER}/${offer.slug}`)}>
			<img
				className={styles.logo}
				src={offer?.image || noImageIcon}
				alt={`${offer?.name}`}
				height={'44px'}
				width={'44px'}
			/>
			<dl>
				<OfferCardColumn title={offer?.categories?.map(({ slug }) => CATEGORIES[slug]).join(', ')} text={offer?.name} />
			</dl>
			<dl className={styles.description}>
				<dt className={styles.textIcon}>
					<Typography.Text type="secondary">{t('Payout')}</Typography.Text>
				</dt>
				<InfoTooltip text={t('Payout description')} size="s" />
			</dl>
			<div className={styles.btn}>
				<Button type="primary" block={!isDesktop} onClick={handleJoinClick}>
					{t('Get feed')}
				</Button>
			</div>
		</div>
	);
};
