import { ISortItem } from '../types/types';

export const getValue = () => {
	const params = new URLSearchParams(window.location.search);
	return params.get('ordering') || '';
};

export const isDesc = () => getValue().startsWith('-');

export const isActive = (sort: ISortItem, defaultSort: ISortItem) =>
	getValue() === sort.name || (!getValue() && sort.name === defaultSort.name);
